#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//#define PAINTEX PAINT, char* szValue//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с переменнымиtypedef struct : public SPROLOZ  {  SValueDef* defOut;  char szText[32];//Для настройки  char szMeas[32];//Единицы измерения  RECT rect;  int    mAlign;  int     mEdge;// Вывод рамки  COLORREF mTxt;// Вывод текста  COLORREF mBkg;// Вывод фона  COLORREF mColor;//фон для моих, зеленый по умолчанию  void PaintDbl( PAINTEX );  void PaintInt( PAINTEX );  void PaintI64( PAINTEX );  void PaintChr( PAINTEX );  void PaintBol( PAINTEX );  void PaintFlt( PAINTEX );  void PaintStr( PAINTEX );  int  nTeg;  UINT eType;  bool bColorEdge;  bool bSelectRect;  char szPointName[64];//имя точки  } Queue_WaterValue;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияvoid Queue_WaterValue::PaintDbl( PAINTEX )  {  SParamValue var(nNumber,defOut);  q.m_pPipe->FillValue( szValue, var, nFloat, NULL );  //int dLength=sizeof(szValue);  //for (int i=0;i<dLength;i++)	 // if (szValue[i]=='.')	 // {		//  szValue[i]=',';		//  return;	 // }  }//void Queue_WaterValue::PaintInt( PAINTEX )  {  SParamValue var(nNumber,defOut);  int i=q.m_pPipe->ValueI(var);  sprintf_s( szValue, 512, "%d", i );  }//void Queue_WaterValue::PaintI64( PAINTEX )  {  ASSERT(0);  }//void Queue_WaterValue::PaintChr( PAINTEX )  {  ASSERT(0);  }//void Queue_WaterValue::PaintBol( PAINTEX )  {  ASSERT(0);  }//void Queue_WaterValue::PaintFlt( PAINTEX )  {  ASSERT(0);  }//void Queue_WaterValue::PaintStr( PAINTEX )  {  ASSERT(0);  }//// Функция отображенияint PaintWaterValue(DefinePaint)  {  QueueP(Queue_WaterValue);  if ((p->mbSelect)&&(p->bSelectRect))  {	  RECT rc=p->rect;      rc.top-=3;	  rc.bottom+=3;	  rc.left-=3;	  rc.right+=3;      CMyPen pen(hDC, 0xffffff, 2 );	  pen.Rect(rc);  }  COLORREF color = p->mTxt;  char szValue[512] = "###";  CShBase* sh = PipeSh;  //  if ( p->defOut == NULL )    {    CMyBrush brush(hDC,0xff00ff);    brush.Rect( p->rect );    }  else  if ( *p->szText )    {    lstrcpy( szValue, p->szText );    }  else  if ( IsTypeOk )    {    color = p->mTxt;    switch ( p->defOut->eVal )      {      case enumValueDbl:p->PaintDbl( hDC, q, szValue );break;      case enumValueInt:p->PaintInt( hDC, q, szValue );break;      case enumValueI64:p->PaintI64( hDC, q, szValue );break;      case enumValueChr:p->PaintChr( hDC, q, szValue );break;      case enumValueBol:p->PaintBol( hDC, q, szValue );break;      case enumValueFlt:p->PaintFlt( hDC, q, szValue );break;      case enumValueStr:p->PaintStr( hDC, q, szValue );break;      };    if ( *p->szMeas )      {      lstrcat( szValue, " " );      lstrcat( szValue, p->szMeas );      }    }  //  if ( p->mBkg != 0xffffffff )    {    CMyBrush brush(hDC,p->mBkg);    brush.Rect( p->rect );    }  //  if(p->bColorEdge)  {	  const double dBadValue=-1021;	  double dHH = TegValueD( p->nTeg, "HH", dBadValue );	  double dH = TegValueD( p->nTeg, "H", dBadValue );	  double dLL = TegValueD( p->nTeg, "LL", dBadValue );	  double dL = TegValueD( p->nTeg, "L", dBadValue );	  char* szValueTemp = (char*)::TegValueS( p->nTeg, "value", "0" );	  if (lstrcmp(szValueTemp,"0")!=0)			lstrcpy(szValue,szValueTemp);	  COLORREF clr=p->mTxt;	  double dValue=atof(szValue);	  if (dL!=dBadValue)		  if (dValue<=dL)			  clr=0x02ccff;	  if (dLL!=dBadValue)          if (dValue<=dLL)			  clr=0x2D3AE4;	  if (dH!=dBadValue)		  if (dValue>=dH)			  clr=0x02ccff;	  if (dHH!=dBadValue)          if (dValue>=dHH)			  clr=0x2D3AE4;	  color=clr;	  CMyBrush brush(hDC,p->mColor);	  brush.Rect( p->rect );	  CMyPen pen(hDC,p->mColor);	  pen.Rect( p->rect );  }    if ( *p->szText )    {	if ( ::IsMnemoStyle(MNEMO_EDIT) )		  color = 0x80ff;    }  if (lstrcmp(szValue,"###")==0)  {	  if ( ::IsMnemoStyle(MNEMO_EDIT) )		  color = 0x80ff;	  else	  {		        char strFormat[16];		  		sprintf_s(strFormat,"%%.%df",p->nFloat);				sprintf_s(szValue,strFormat,0);	  }  }  CMyFont font( hDC, NULL, color );  font.DrawS( p->rect, szValue, p->mAlign );  //  if ( p->mEdge )    ::DrawEdge( hDC, &p->rect, p->mEdge, BF_RECT );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int PressWaterValue(DefinePress){  Queue_WaterValue* p = (Queue_WaterValue*)s;  if ((p->bSelectRect)&& ( nCode == 2 ))  {		::SendMessage  ( q.hWnd, nBuildQueue, BUILD_SELECT, (LPARAM)(&p->mbSelect) );		::SendMsg(q.hWnd,QUEUE_SELPOINT,(LPARAM)&p->szPointName);  }  return 0;}void AddWaterValue(DefineTegs)  {  AddQueueEx(Queue_WaterValue);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint  = &PaintWaterValue;  p->press=&PressWaterValue;  p->mBkg   = 0xffffffff;  p->mColor=RGB(0,255,0);  p->mAlign = DT_CENTER;  p->bColorEdge=false;  char szObj[32] = "sensor";  char szHS[64] = "";  p->bSelectRect=false;  //  STegObj obj[] =    {    { 'I', "edge" , &p->mEdge    },    { 'A', "txt"  , &p->mTxt     },    { 'A', "bkg"  , &p->mBkg     },    { 'I', "align", &p->mAlign   },    { 'S', "text" ,  p->szText,31},    { 'S', "meas" ,  p->szMeas,31},    { 'S', "obj"  ,  szObj,31},	{ 'B', "colorEdge",&p->bColorEdge},	{ 'A', "color"  , &p->mColor     },	{ 'B',"select", &p->bSelectRect},    // Дополнительная информация    EXT_QUEUE    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  // Форматы: (Name.Param) | (Name) | (.Param) | (.)  // Текущий активный элемент  bool bActive = *teg[0].value == '.';  static char* DEF = "PV";  char* parm = strchr( teg[0].value, '.' );  if ( parm == NULL ) parm = DEF;  else *parm++ = 0;  //  lstrcpy(p->szPointName,teg[0].value);  UINT eType;  if ( bActive )    {    p->nNumber = def.GetActiveObj();    eType = def.GetMnemoType( p->nNumber );    }  else    {    eType = TextToType( szObj );    p->nNumber = def.AddKindEx( eType, teg[0].value );    }  if (p->bColorEdge)  {		p->nTeg = ::FindTagEx( teg[0].value, eType );  }  p->eType=eType;  p->defOut = NameToValue( eType, parm );  ASSERT( p->defOut != NULL );  //  p->rect = p->mRect;  if ( p->mEdge != 0 )// Чтобы рамка не наезжала на текст    ::InflateRect( &p->rect, -2, -2 );  //if ( !::IsMnemoStyle(MNEMO_EDIT) )  //  ::SetRectEmpty( &p->mRect );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~